export function intrinsicMetacognition(reasoningPaths) {
  const scores = reasoningPaths.map(path => {
    const consistency = path.reduce((acc, step) => acc + step.confidence, 0) / path.length;
    return { path, consistency };
  });
  const bestPath = scores.reduce((best, current) => current.consistency > best.consistency ? current : best, scores[0]);
  return bestPath;
}